<script lang="ts">
 import {auth} from '#lib/auth.svelte.ts';
 import {anyApi} from 'convex/server';
 import {Check,ShieldCheck,ArrowRight,Copy,LockKeyhole} from 'lucide-svelte';
 import type {CheckoutResult} from '../../../convex/lib/flutterwave';
 type Provider='flutterwave'|'korapay';
 type Transfer=Extract<CheckoutResult,{kind:'bankTransfer'}>;
 interface Subscription {active:boolean;paidActive:boolean;accountStatus:string;expiresAt:number|null;pendingReference?:string|null;pendingProvider?:Provider|null;pendingCheckoutUrl?:string|null;pendingInstructions?:Transfer|null;gateways:Record<Provider,boolean>;recent:{reference:string;provider:Provider;status:string;amount:number;createdAt:number}[]}
 let subscription=$state<Subscription|null>(null),instructions=$state<Transfer|null>(null),busy=$state(false),error=$state(''),copied=$state(false),paymentStatus=$state('');
 let returnedReference=$state<string|null>(null),returnChecked=$state(false);
 import {onMount,untrack} from 'svelte';
 onMount(()=>{const params=new URLSearchParams(window.location.search);const value=params.get('reference')??params.get('tx_ref');if(value&&/^pe_[a-zA-Z0-9_-]{1,95}$/.test(value))returnedReference=value;});
 $effect(()=>{const client=auth.client;if(!client){subscription=null;instructions=null;return;}return untrack(()=>client.onUpdate(anyApi.payments.mine,{},value=>{subscription=value;if(instructions&&value?.recent.some((p:{reference:string;status:string})=>p.reference===instructions?.reference&&p.status==='paid')){instructions=null;paymentStatus='Payment verified. Your membership is active.';}if(value?.pendingInstructions&&!instructions)instructions=value.pendingInstructions;},()=>error='Payment account details could not load. Refresh this page or try again later.'));});
 $effect(()=>{if(auth.client&&subscription&&returnedReference&&!returnChecked){returnChecked=true;void checkPayment(returnedReference);}});
 async function checkout(provider:Provider){if(!auth.client)return;busy=true;error='';paymentStatus='';try{const result=await auth.client.action(anyApi.payments.checkout,{provider}) as CheckoutResult;if(result.kind==='redirect')window.location.assign(result.url);else instructions=result;}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function checkPayment(requested?:string){const reference=requested??instructions?.reference??subscription?.pendingReference;if(!auth.client||!reference)return;busy=true;error='';try{const result=await auth.client.action(anyApi.payments.checkStatus,{reference});paymentStatus=result.paid?'Payment verified. Your membership is active.':'No successful payment has been confirmed yet. You can check again after 30 seconds. Payment confirmation may take a few minutes.';if(result.paid)instructions=null;}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function copy(){if(!instructions)return;try{await navigator.clipboard.writeText(instructions.accountNumber);copied=true;}catch{error='Copy the account number shown below into your banking app.';}}
</script>
<svelte:head><title>All-access checkout — PuntersEdge</title></svelte:head>
<div class="mx-auto max-w-5xl py-6 sm:py-10">
<header class="max-w-2xl"><p class="text-sm font-semibold uppercase tracking-widest text-model">One membership. Every sport.</p><h1 class="mt-3 text-4xl font-extrabold sm:text-5xl">Exclusive VIP Punter membership.</h1><p class="mt-4 text-haze">Live fixture analysis, model probabilities and the tools to review your decisions in one place.</p></header>
<div class="mt-8 grid gap-6 lg:grid-cols-2">
<section class="surface p-6 sm:p-8"><span class="rounded-full tint-pop px-3 py-1 text-xs font-bold text-pop">EXCLUSIVE VIP PUNTER</span><p class="mt-6 text-5xl font-extrabold">₦10,000<span class="ml-2 text-base font-normal text-haze">/ month</span></p><p class="mt-3 text-sm text-haze">One calendar month per verified payment. Renew when you choose; no automatic debit.</p><ul class="mt-7 space-y-4">{#each ['All five sport dashboards and provider fixtures','Published forecasts, probabilities and quoted markets','Advanced bet machine and full ticket preview','Saved betslips, designed PDF','Post-match reviews and verified score updates','Agnes AI explanations within daily usage limits'] as benefit}<li class="flex items-start gap-3"><Check class="mt-0.5 h-5 w-5 shrink-0 text-model" /><span>{benefit}</span></li>{/each}</ul><p class="mt-7 rounded-xl bg-ink p-4 text-xs leading-relaxed text-haze">Forecasts describe uncertain outcomes. Membership does not guarantee winning selections or returns.</p></section>
<section class="surface self-start p-6 sm:p-8"><div class="flex items-center gap-3"><ShieldCheck class="h-7 w-7 text-model" /><h2 class="text-2xl font-bold">Secure checkout</h2></div>
{#if auth.viewer?.superAdmin}<p class="mt-5 rounded-xl tint-model p-4 text-model">Your super-admin role includes full access. No subscription payment is required.</p><a class="btn-primary mt-5 inline-flex" href="/admin">Open admin console</a>
{:else if !auth.signedIn}<p class="mt-5 text-haze">Create your account or sign in before checkout so payment activates the correct membership.</p><a class="btn-primary mt-5 flex items-center justify-center gap-2" href="/login?next=/subscribe">Sign in to continue<ArrowRight size={18} /></a><a class="mt-4 block text-center text-sm font-semibold text-pop" href="/signup?next=/subscribe">Create an account</a>
{:else}
<p class="mt-5 text-sm text-haze">Membership for <strong class="text-chalk">{auth.viewer?.email}</strong></p>
{#if subscription?.expiresAt&&!subscription.active}<p role="status" class="mt-4 rounded-xl tint-book p-4 text-sm text-book">Your previous access has expired. Renew below to restore the full application.</p>{/if}{#if subscription?.accountStatus&&subscription.accountStatus!=='active'}<p role="alert" class="mt-4 rounded-xl tint-loss p-4 text-loss">This account is {subscription.accountStatus}. Contact support before making a payment.</p>{/if}{#if subscription?.active}<div class="mt-4 rounded-xl tint-model p-4"><p class="font-semibold text-model">Membership active</p>{#if subscription.expiresAt}<p class="mt-1 text-sm">Valid until {new Date(subscription.expiresAt).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'})} WAT.</p>{/if}</div>{/if}
{#if instructions}<div class="mt-5 rounded-2xl bg-ink p-5 ring-1 ring-line"><h3 class="text-lg font-bold">Transfer ₦10,000</h3><p class="mt-2 text-sm text-haze">Use your banking app to pay this temporary Flutterwave account.</p><dl class="mt-5 space-y-3"><div><dt class="text-xs text-haze">Bank</dt><dd class="font-semibold">{instructions.bankName}</dd></div><div><dt class="text-xs text-haze">Account number</dt><dd class="flex items-center gap-3 text-2xl font-bold tracking-wide">{instructions.accountNumber}<button onclick={copy} aria-label="Copy account number" class="rounded-lg p-2 ring-1 ring-line"><Copy size={18} /></button></dd>{#if copied}<p class="text-xs text-model" role="status">Account number copied</p>{/if}</div><div><dt class="text-xs text-haze">Account name</dt><dd>{instructions.accountName}</dd></div><div><dt class="text-xs text-haze">Payment reference</dt><dd class="break-all text-sm">{instructions.reference}</dd></div><div><dt class="text-xs text-haze">Expires</dt><dd class="text-sm">{new Date(instructions.expiresAt).toLocaleString('en-NG',{timeZone:'Africa/Lagos'})} WAT</dd></div></dl><p class="mt-4 text-xs text-haze">Do not reuse this temporary account. Access activates after verified bank confirmation, not after clicking a button.</p><button class="btn-secondary mt-4" onclick={()=>instructions=null}>Close instructions</button></div>
{:else}<dl class="mt-5 space-y-3 rounded-xl bg-ink p-4 text-sm"><div class="flex justify-between"><dt class="text-haze">Exclusive VIP monthly plan</dt><dd>₦10,000</dd></div><div class="flex justify-between border-t border-line pt-3 font-bold"><dt>Amount to pay</dt><dd>₦10,000 NGN</dd></div></dl><div class="mt-5 grid gap-3">{#each [['flutterwave','Flutterwave'],['korapay','Korapay']] as [provider,label]}<button class="btn-primary flex min-h-12 w-full items-center justify-center gap-2" disabled={busy||!subscription?.gateways[provider as Provider]||subscription?.accountStatus!=='active'} onclick={()=>checkout(provider as Provider)}>{busy?'Preparing secure checkout…':subscription?.active?`Extend membership with ${label}`:`Pay with ${label}`}<ArrowRight size={18}/></button>{#if subscription&&!subscription.gateways[provider as Provider]}<p class="text-xs text-haze">{label} checkout is currently unavailable.</p>{/if}{/each}</div>{#if subscription?.pendingCheckoutUrl}<a class="btn-ghost mt-4 w-full" href={subscription.pendingCheckoutUrl}>Resume pending {subscription.pendingProvider} checkout</a>{/if}{/if}
{/if}
{#if auth.signedIn && (instructions || subscription?.pendingReference)}<button class="btn-secondary mt-5 w-full" disabled={busy} onclick={()=>checkPayment()}>{busy?'Checking…':'I have paid · check payment status'}</button>{/if}
{#if paymentStatus}<p role="status" class="mt-4 text-sm text-model">{paymentStatus}</p>{/if}
{#if subscription?.recent.length}<details class="mt-5 rounded-xl border border-line p-4"><summary class="min-h-11 cursor-pointer font-semibold">Your recent payment attempts</summary><ul class="mt-3 space-y-3 text-sm">{#each subscription.recent as payment}<li class="border-t border-line pt-3"><p>{payment.provider} · {payment.status.replaceAll('_',' ')} · ₦{payment.amount.toLocaleString('en-NG')}</p><p class="mt-1 break-all text-xs text-haze">{payment.reference}</p><p class="mt-1 text-xs text-haze">{new Date(payment.createdAt).toLocaleString('en-NG',{timeZone:'Africa/Lagos'})} WAT</p></li>{/each}</ul></details>{/if}
{#if error}<p role="alert" class="mt-4 rounded-xl tint-loss p-3 text-sm text-loss">{error}</p>{/if}<p class="mt-5 flex items-center gap-2 text-xs text-haze"><LockKeyhole size={14} /> Payment is verified server-side before access is granted.</p>
</section>
</div></div>
